"use client"

import { useState, useTransition } from "react"
import Link from "next/link"
import { useRouter } from "next/navigation"
import {
  approveMemberRequest,
  rejectMemberRequest,
  closeGroupRequest,
  deleteGroupRequest,
  updateGroupRequest,
  removeApprovedMember,
} from "@/actions/groupRequest"

function StatusBadge({ status }) {
  const config = {
    pending: { label: "Pending", bg: "bg-amber-50", text: "text-amber-500", border: "border-amber-100" },
    approved: { label: "Approved", bg: "bg-emerald-50", text: "text-emerald-500", border: "border-emerald-100" },
    rejected: { label: "Rejected", bg: "bg-rose-50", text: "text-rose-400", border: "border-rose-100" },
  }
  const c = config[status] || config.pending
  return (
    <span className={`text-[9px] font-black uppercase tracking-widest px-3 py-1.5 rounded-lg border ${c.bg} ${c.text} ${c.border}`}>
      {c.label}
    </span>
  )
}

function MemberRequestCard({ memberRequest, onApprove, onReject, onRemove, groupRequestId }) {
  const [isPending, startTransition] = useTransition()
  const [error, setError] = useState("")
  const [showConfirm, setShowConfirm] = useState(false)

  const user = memberRequest.user
  const isProcessed = memberRequest.status !== "pending"
  const isApproved = memberRequest.status === "approved"

  const handleApprove = () => {
    setError("")
    startTransition(async () => {
      const result = await onApprove(memberRequest._id.toString())
      if (result?.error) setError(result.error)
    })
  }

  const handleReject = () => {
    setError("")
    startTransition(async () => {
      const result = await onReject(memberRequest._id.toString())
      if (result?.error) setError(result.error)
    })
  }

  const handleRemove = () => {
    setError("")
    startTransition(async () => {
      const result = await onRemove(memberRequest._id.toString(), groupRequestId)
      if (result?.error) {
        setError(result.error)
        setShowConfirm(false)
      }
    })
  }

  return (
    <div className={`bg-white rounded-[2rem] border transition-all ${
      isApproved ? "border-emerald-100" :
      memberRequest.status === "rejected" ? "border-rose-100 opacity-60" :
      "border-slate-100 hover:border-sky-100 hover:shadow-md hover:shadow-sky-500/5"
    }`}>
      <div className="p-6">
        <div className="flex items-center gap-4 mb-4">
          <div className="w-12 h-12 bg-slate-50 rounded-[1.25rem] flex items-center justify-center text-sm font-black text-slate-400 flex-shrink-0">
            {user?.fullname?.charAt(0) || user?.username?.charAt(0) || "?"}
          </div>
          <div className="flex-1 min-w-0">
            <p className="font-black text-slate-800 text-sm truncate">
              {user?.fullname || user?.username || "Unknown User"}
            </p>
            <p className="text-[10px] text-slate-400 font-bold truncate">{user?.email || "—"}</p>
          </div>
          <StatusBadge status={memberRequest.status} />
        </div>

        <p className="text-[9px] text-slate-300 font-bold uppercase tracking-widest mb-4">
          Requested {new Date(memberRequest.createdAt).toLocaleDateString("id-ID", {
            day: "numeric", month: "short", year: "numeric"
          })}
        </p>

        {error && (
          <p className="text-rose-400 text-[10px] font-bold uppercase tracking-wider mb-3">{error}</p>
        )}

        {/* Action buttons — pending */}
        {!isProcessed && (
          <div className="flex gap-3">
            <button onClick={handleApprove} disabled={isPending}
              className="flex-1 bg-emerald-500 hover:bg-emerald-400 text-white py-3 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all active:scale-95 disabled:opacity-40 shadow-lg shadow-emerald-500/10">
              {isPending ? "..." : "✓ Approve"}
            </button>
            <button onClick={handleReject} disabled={isPending}
              className="flex-1 bg-slate-100 hover:bg-rose-50 text-slate-400 hover:text-rose-400 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all active:scale-95 disabled:opacity-40">
              {isPending ? "..." : "✕ Reject"}
            </button>
          </div>
        )}

        {/* Remove button — approved */}
        {isApproved && (
          <>
            {!showConfirm ? (
              <button onClick={() => setShowConfirm(true)} disabled={isPending}
                className="w-full bg-slate-50 hover:bg-rose-50 text-slate-300 hover:text-rose-400 border border-slate-100 hover:border-rose-100 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all disabled:opacity-40">
                Remove Member
              </button>
            ) : (
              <div className="flex gap-2">
                <button onClick={() => setShowConfirm(false)} disabled={isPending}
                  className="flex-1 bg-slate-100 text-slate-400 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all">
                  Cancel
                </button>
                <button onClick={handleRemove} disabled={isPending}
                  className="flex-1 bg-rose-500 hover:bg-rose-400 text-white py-3 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all active:scale-95 disabled:opacity-40">
                  {isPending ? "..." : "Confirm"}
                </button>
              </div>
            )}
          </>
        )}
      </div>
    </div>
  )
}

// Modal Edit GroupRequest
function EditModal({ groupRequest, masterServices, onClose, onSave }) {
  const [isPending, startTransition] = useTransition()
  const [error, setError] = useState("")
  const [serviceName, setServiceName] = useState(groupRequest.serviceName || "")
  const [title, setTitle] = useState(groupRequest.title || "")
  const [description, setDescription] = useState(groupRequest.description || "")
  const [maxSlot, setMaxSlot] = useState(groupRequest.maxSlot || 1)
  const [search, setSearch] = useState("")

  const inputStyles = "w-full p-3 bg-slate-50 border border-slate-100 rounded-2xl outline-none focus:bg-white focus:border-sky-400 text-sm font-bold text-slate-700 transition-all placeholder:text-slate-300"

  const filteredServices = (masterServices || []).filter((s) =>
    s.serviceName?.toLowerCase().includes(search.toLowerCase())
  )

  const handleSave = () => {
    setError("")
    startTransition(async () => {
      const formData = new FormData()
      formData.append("serviceName", serviceName)
      formData.append("title", title)
      formData.append("description", description)
      formData.append("maxSlot", maxSlot)
      const result = await onSave(formData)
      if (result?.error) setError(result.error)
      else onClose()
    })
  }

  return (
    <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-50 flex items-center justify-center p-6">
      <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-2xl p-8 max-w-lg w-full max-h-[90vh] overflow-y-auto">
        <div className="flex items-center justify-between mb-6">
          <h3 className="text-lg font-black text-slate-800">Edit Group</h3>
          <button onClick={onClose} className="text-slate-300 hover:text-slate-500 font-black text-xl">✕</button>
        </div>

        <div className="space-y-5">
          {/* Service Name */}
          <div>
            <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 tracking-widest">Service</label>
            <input
              type="text"
              value={search || serviceName}
              onChange={(e) => { setSearch(e.target.value); setServiceName(e.target.value) }}
              placeholder="Search or type service name..."
              className={inputStyles}
            />
            {search && filteredServices.length > 0 && (
              <div className="mt-2 border border-slate-100 rounded-2xl overflow-hidden max-h-40 overflow-y-auto">
                {filteredServices.map((svc) => (
                  <div key={svc._id}
                    onClick={() => { setServiceName(svc.serviceName); setSearch("") }}
                    className="flex items-center gap-3 p-3 hover:bg-slate-50 cursor-pointer border-b border-slate-50 last:border-0">
                    {svc.logo && <img src={svc.logo} className="w-5 h-5 object-contain" alt={svc.serviceName} />}
                    <span className="text-sm font-bold text-slate-700">{svc.serviceName}</span>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* Title */}
          <div>
            <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 tracking-widest">Title</label>
            <input type="text" value={title} onChange={(e) => setTitle(e.target.value)} className={inputStyles} />
          </div>

          {/* Description */}
          <div>
            <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 tracking-widest">Description</label>
            <textarea value={description} onChange={(e) => setDescription(e.target.value)}
              rows={3} className={inputStyles + " resize-none"} />
          </div>

          {/* Max Slot */}
          <div>
            <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 tracking-widest">Max Slots</label>
            <div className="flex items-center gap-4">
              <button type="button" onClick={() => setMaxSlot((v) => Math.max(1, v - 1))}
                className="w-10 h-10 rounded-xl bg-slate-100 text-slate-500 font-black text-lg hover:bg-slate-200 transition flex items-center justify-center">−</button>
              <span className="text-2xl font-black text-slate-800 flex-1 text-center">{maxSlot}</span>
              <button type="button" onClick={() => setMaxSlot((v) => Math.min(20, v + 1))}
                className="w-10 h-10 rounded-xl bg-slate-100 text-slate-500 font-black text-lg hover:bg-slate-200 transition flex items-center justify-center">+</button>
            </div>
          </div>

          {error && (
            <div className="p-3 bg-rose-50 rounded-2xl border border-rose-100">
              <p className="text-rose-400 text-[10px] font-bold uppercase tracking-wider">{error}</p>
            </div>
          )}

          <div className="flex gap-3 pt-2">
            <button onClick={onClose} disabled={isPending}
              className="flex-1 bg-slate-100 text-slate-500 py-3.5 rounded-2xl font-black text-[10px] uppercase tracking-widest transition-all disabled:opacity-40">
              Cancel
            </button>
            <button onClick={handleSave} disabled={isPending || !serviceName || !title}
              className="flex-1 bg-sky-500 hover:bg-sky-400 text-white py-3.5 rounded-2xl font-black text-[10px] uppercase tracking-widest transition-all active:scale-95 disabled:opacity-40">
              {isPending ? "Saving..." : "Save Changes"}
            </button>
          </div>
        </div>
      </div>
    </div>
  )
}

// Modal konfirmasi delete
function DeleteModal({ onConfirm, onCancel, isPending }) {
  return (
    <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-50 flex items-center justify-center p-6">
      <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-2xl p-8 max-w-sm w-full">
        <div className="w-14 h-14 bg-rose-50 rounded-[1.5rem] flex items-center justify-center mx-auto mb-6">
          <span className="text-2xl">🗑️</span>
        </div>
        <h3 className="text-lg font-black text-slate-800 text-center mb-2">Delete Group?</h3>
        <p className="text-sm text-slate-400 font-medium text-center mb-8 leading-relaxed">
          This will permanently delete the group along with all member requests and members. This action cannot be undone.
        </p>
        <div className="flex gap-3">
          <button onClick={onCancel} disabled={isPending}
            className="flex-1 bg-slate-100 hover:bg-slate-200 text-slate-500 py-3.5 rounded-2xl font-black text-[10px] uppercase tracking-widest transition-all disabled:opacity-40">
            Cancel
          </button>
          <button onClick={onConfirm} disabled={isPending}
            className="flex-1 bg-rose-500 hover:bg-rose-400 text-white py-3.5 rounded-2xl font-black text-[10px] uppercase tracking-widest transition-all active:scale-95 disabled:opacity-40 shadow-lg shadow-rose-500/20">
            {isPending ? "Deleting..." : "Yes, Delete"}
          </button>
        </div>
      </div>
    </div>
  )
}

export default function ManageGroupRequestClient({ groupRequest, memberRequests, masterServices }) {
  const router = useRouter()
  const [isPending, startTransition] = useTransition()
  const [error, setError] = useState("")
  const [showDeleteModal, setShowDeleteModal] = useState(false)
  const [showEditModal, setShowEditModal] = useState(false)

  const pendingCount = memberRequests.filter(r => r.status === "pending").length
  const approvedCount = memberRequests.filter(r => r.status === "approved").length

  const handleApprove = async (memberRequestId) => {
    const result = await approveMemberRequest(memberRequestId)
    if (!result?.error) router.refresh()
    return result
  }

  const handleReject = async (memberRequestId) => {
    const result = await rejectMemberRequest(memberRequestId)
    if (!result?.error) router.refresh()
    return result
  }

  const handleRemove = async (memberRequestId, groupRequestId) => {
    const result = await removeApprovedMember(memberRequestId, groupRequestId)
    if (!result?.error) router.refresh()
    return result
  }

  const handleClose = () => {
    startTransition(async () => {
      const result = await closeGroupRequest(groupRequest._id.toString())
      if (result?.error) setError(result.error)
      else router.push("/dashboard/group-requests")
    })
  }

  const handleDelete = () => {
    startTransition(async () => {
      const result = await deleteGroupRequest(groupRequest._id.toString())
      if (result?.error) {
        setError(result.error)
        setShowDeleteModal(false)
      } else {
        router.push("/dashboard/group-requests")
      }
    })
  }

  const handleSaveEdit = async (formData) => {
    const result = await updateGroupRequest(groupRequest._id.toString(), formData)
    if (!result?.error) router.refresh()
    return result
  }

  const statusConfig = {
    open: { label: "Open", bg: "bg-emerald-50", text: "text-emerald-500", border: "border-emerald-100" },
    full: { label: "Full", bg: "bg-amber-50", text: "text-amber-500", border: "border-amber-100" },
    closed: { label: "Closed", bg: "bg-slate-100", text: "text-slate-400", border: "border-slate-200" },
  }
  const sc = statusConfig[groupRequest.status] || statusConfig.open

  return (
    <div className="min-h-screen bg-[#F8FAFC] p-6 md:p-12 font-sans text-slate-900">
      <div className="max-w-4xl mx-auto">

        {/* Header */}
        <div className="flex items-center justify-between mb-12">
          <div>
            <Link href="/dashboard/group-requests"
              className="group inline-flex items-center gap-2 text-slate-400 hover:text-sky-500 transition-colors mb-4">
              <span className="text-xl group-hover:-translate-x-1 transition-transform">←</span>
              <span className="text-[10px] font-black uppercase tracking-[0.2em]">My Groups</span>
            </Link>
            <h1 className="text-4xl font-black tracking-tight text-slate-900">
              Manage <span className="text-sky-500">Requests.</span>
            </h1>
            <p className="text-[11px] text-slate-400 font-black uppercase tracking-[0.2em] mt-1">
              {pendingCount} Pending · {approvedCount} Approved
            </p>
          </div>

          {/* Action buttons */}
          <div className="flex items-center gap-2 flex-wrap justify-end">
            {/* Edit */}
            <button onClick={() => setShowEditModal(true)} disabled={isPending}
              className="bg-white border border-slate-100 px-5 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest text-slate-500 hover:text-sky-500 hover:border-sky-100 transition-all shadow-sm disabled:opacity-40">
              Edit
            </button>

            {/* Close — hanya saat open */}
            {groupRequest.status === "open" && (
              <button onClick={handleClose} disabled={isPending}
                className="bg-white border border-slate-100 px-5 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest text-slate-500 hover:text-amber-500 hover:border-amber-100 transition-all shadow-sm disabled:opacity-40">
                Close
              </button>
            )}

            {/* Delete */}
            <button onClick={() => setShowDeleteModal(true)} disabled={isPending}
              className="bg-white border border-slate-100 px-5 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest text-slate-500 hover:text-rose-400 hover:border-rose-100 transition-all shadow-sm disabled:opacity-40">
              Delete
            </button>
          </div>
        </div>

        {/* Info Card */}
        <div className="bg-white rounded-[2.5rem] border border-slate-50 shadow-sm p-8 mb-10">
          <div className="flex items-center gap-6">
            <div className="w-16 h-16 bg-slate-50 rounded-[1.5rem] flex items-center justify-center border border-slate-100 flex-shrink-0">
              {groupRequest.logo ? (
                <img src={groupRequest.logo} className="w-9 h-9 object-contain" alt={groupRequest.serviceName} />
              ) : (
                <span className="text-sky-400 text-2xl font-black uppercase">
                  {groupRequest.serviceName?.charAt(0) || groupRequest.title?.charAt(0)}
                </span>
              )}
            </div>

            <div className="flex-1 min-w-0">
              <div className="flex items-center gap-3 mb-1 flex-wrap">
                <h2 className="text-xl font-black text-slate-800">{groupRequest.title}</h2>
                <span className={`text-[9px] font-black uppercase tracking-widest px-3 py-1 rounded-lg border ${sc.bg} ${sc.text} ${sc.border}`}>
                  {sc.label}
                </span>
              </div>
              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-wider mb-1">{groupRequest.serviceName}</p>
              {groupRequest.description && (
                <p className="text-sm text-slate-400 font-medium">{groupRequest.description}</p>
              )}
            </div>

            <div className="text-right flex-shrink-0">
              <p className="text-[9px] font-black text-slate-400 uppercase tracking-wider mb-1">Slots</p>
              <p className="text-2xl font-black text-slate-800">
                {groupRequest.availableSlot}
                <span className="text-slate-300 text-sm font-bold"> / {groupRequest.maxSlot}</span>
              </p>
            </div>
          </div>

          {error && (
            <div className="mt-4 p-4 bg-rose-50 rounded-2xl border border-rose-100">
              <p className="text-rose-400 text-[10px] font-bold uppercase tracking-wider">{error}</p>
            </div>
          )}
        </div>

        {/* Member Requests */}
        <div className="space-y-6">
          <div className="flex items-center justify-between px-2">
            <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em]">Incoming Requests</h2>
            <div className="h-px flex-1 bg-slate-100 mx-6 hidden md:block"></div>
            <span className="text-[10px] font-black text-slate-400 uppercase tracking-wider">{memberRequests.length} Total</span>
          </div>

          {memberRequests.length === 0 ? (
            <div className="text-center py-24 bg-white rounded-[3rem] border-2 border-dashed border-slate-100">
              <div className="w-16 h-16 bg-slate-50 rounded-[1.5rem] flex items-center justify-center mx-auto mb-4">
                <span className="text-2xl text-slate-200 font-black">?</span>
              </div>
              <h3 className="text-slate-900 font-black mb-1">No Requests Yet</h3>
              <p className="text-slate-400 font-bold uppercase tracking-widest text-[9px]">
                Share your group link so others can find it.
              </p>
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {memberRequests.map((req) => (
                <MemberRequestCard
                  key={req._id.toString()}
                  memberRequest={req}
                  groupRequestId={groupRequest._id.toString()}
                  onApprove={handleApprove}
                  onReject={handleReject}
                  onRemove={handleRemove}
                />
              ))}
            </div>
          )}
        </div>
      </div>

      {/* Edit Modal */}
      {showEditModal && (
        <EditModal
          groupRequest={groupRequest}
          masterServices={masterServices}
          onClose={() => setShowEditModal(false)}
          onSave={handleSaveEdit}
        />
      )}

      {/* Delete Modal */}
      {showDeleteModal && (
        <DeleteModal
          onConfirm={handleDelete}
          onCancel={() => setShowDeleteModal(false)}
          isPending={isPending}
        />
      )}
    </div>
  )
}